n\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e  // real trigger registers, and stands in again if that one unmounts. Both are\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e  // state, so a trigger arriving while the panel is open re-anchors it.\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"k1w4712\"\u003e  const\u003c/span\u003e\u003cspan class=\"kcm9rcr\"\u003e anchorRef\u003c/span\u003e\u003cspan class=\"k1w4712\"\u003e =\u003c/span\u003e\u003cspan class=\"kc3y0eb\"\u003e useMemo\u003c/span\u003e\u003cspan class=\"k20f01c\"\u003e\u0026#x3C;\u003c/span\u003e\u003cspan class=\"k1azllp\"\u003eReact\u003c/span\u003e\u003cspan class=\"k20f01c\"\u003e.\u003c/span\u003e\u003cspan class=\"k1azllp\"\u003eMutableRefObject\u003c/span\u003e\u003cspan class=\"k20f01c\"\u003e\u0026#x3C;\u003c/span\u003e\u003cspan class=\"k1azllp\"\u003eHTMLElement\u003c/span\u003e\u003cspan class=\"k1w4712\"\u003e |\u003c/span\u003e\u003cspan class=\"kcm9rcr\"\u003e null\u003c/span\u003e\u003cspan class=\"k20f01c\"\u003e\u003e\u003e(\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"k20f01c\"\u003e    () \u003c/span\u003e\u003cspan class=\"k1w4712\"\u003e=\u003e\u003c/span\u003e\u003cspan class=\"k20f01c\"\u003e ({ current: trigger \u003c/span\u003e\u003cspan class=\"k1w4712\"\u003e??\u003c/span\u003e\u003cspan class=\"k20f01c\"\u003e root }),\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"k20f01c\"\u003e    [root, trigger],\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"k20f01c\"\u003e  );\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e  // The panel is a `role=\"dialog\"` and goes inert the moment it closes, so\u003c/span\u003e\u003c/span\u003e\n\