\"\u003e;\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e  /** Draw the surface shadow. Default true. */\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"k1azllp\"\u003e  shadow\u003c/span\u003e\u003cspan class=\"k1w4712\"\u003e?:\u003c/span\u003e\u003cspan class=\"kcm9rcr\"\u003e boolean\u003c/span\u003e\u003cspan class=\"k20f01c\"\u003e;\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e  /**\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e   * Runs after the portalled surface is positioned and visible. Passing it\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e   * hands focus to the caller: the panel then moves no focus on its own.\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e   */\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kc3y0eb\"\u003e  onOpenAutoFocus\u003c/span\u003e\u003cspan class=\"k1w4712\"\u003e?:\u003c/span\u003e\u003cspan class=\"k20f01c\"\u003e (\u003c/span\u003e\u003cspan class=\"k1azllp\"\u003econtent\u003c/span\u003e\u003cspan class=\"k1w4712\"\u003e:\u003c/span\u003e\u003cspan class=\"k1azllp\"\u003e HTMLDivElement\u003c/span\u003e\u003cspan class=\"k20f01c\"\u003e) \u003c/span\u003e\u003cspan class=\"k1w4712\"\u003e=\u003e\u003c/span\u003e\u003cspan class=\"kcm9rcr\"\u003e void\u003c/span\u003e\u003cspan class=\"k20f01c\"\u003e;\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e  /**\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e   * Element to focus when the trigger opens the panel by keyboard. Defaults\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan class=\"kn5u410\"\u003e   * 